# Arena de Robôs (laboratório do Diver): as regras da luta. Colado no robô (distância 1), "andar" é ficar parado. Nada aqui é sorteado na hora: os robôs seguem padrões
# fixos (o Titã usa um sorteio com semente fixa), então a mesma estratégia dá sempre a mesma luta.
import random as _random

ROBOS = {
    "Parafuso": {"vida": 10, "descricao": "só sabe andar"},
    "Ferrugem": {"vida": 10, "descricao": "anda até você e ataca sem parar"},
    "Pistão": {"vida": 10, "descricao": "colado em você, alterna entre defender e atacar"},
    "Faísca": {"vida": 13, "descricao": "carrega um golpe forte, solta, e ataca uma vez"},
    "Titã": {"vida": 14, "descricao": "o chefe: mistura tudo, com um sorteio de semente fixa"},
}

def _robo(nome, s, n, sorteio):
    if s["distancia"] > 1:
        return "andar"
    if nome == "Parafuso":
        return "andar"
    if nome == "Ferrugem":
        return "atacar"
    if nome == "Pistão":
        return "defender" if n % 2 == 0 else "atacar"
    if nome == "Faísca":
        return ["carregar", "atacar", "atacar"][n % 3]
    if s["robo_carregando"]:
        return "atacar"
    return sorteio.choice(["atacar", "atacar", "defender", "carregar"])

def lutar(decidir, nome="Parafuso", mostrar=True):
    sorteio = _random.Random(2026)
    voce, robo = 10, ROBOS[nome]["vida"]
    total = robo
    s = {"distancia": 4, "minha_vida": voce, "vida_robo": robo, "turno": 1,
         "minha_ultima": "", "ultima_do_robo": "", "robo_carregando": False}
    colado = 0
    if mostrar:
        print(f"Arena: você (10) contra {nome} ({robo}), {ROBOS[nome]['descricao']}.")
    for turno in range(1, 21):
        s["turno"], s["minha_vida"], s["vida_robo"] = turno, voce, robo
        minha = decidir(dict(s))
        if minha not in ("andar", "atacar", "defender"):
            raise ValueError(f'decidir devolveu {minha!r}; use "andar", "atacar" ou "defender"')
        dele = _robo(nome, s, colado, sorteio)
        if s["distancia"] == 1:
            colado += 1
        escudo = minha == "defender" and s["minha_ultima"] != "defender"
        escudo_dele = dele == "defender" and s["ultima_do_robo"] != "defender"
        forte = s["robo_carregando"]
        perto = s["distancia"] == 1
        dano_voce = dano_robo = 0
        if perto and minha == "atacar":
            if escudo_dele:
                dano_robo, dano_voce = dano_robo + 1, dano_voce + 2
            else:
                dano_robo += 3
        if perto and dele == "atacar":
            golpe = 6 if forte else 3
            if escudo:
                dano_voce, dano_robo = dano_voce + 1, dano_robo + 2
            else:
                dano_voce += golpe
        for quem in (minha, dele):
            if quem == "andar" and s["distancia"] > 1:
                s["distancia"] -= 1
        voce, robo = voce - dano_voce, robo - dano_robo
        s["minha_ultima"], s["ultima_do_robo"] = minha, dele
        s["robo_carregando"] = dele == "carregar"
        if mostrar:
            barra = lambda v, t: "#" * -(-max(v, 0) * 5 // t) + "." * (5 - -(-max(v, 0) * 5 // t))
            print(f"T{turno:02d} você: {minha:<8} robô: {dele}")
            print(f"    você {max(voce, 0):>2} {barra(voce, 10)} | robô {max(robo, 0):>2} {barra(robo, total)}")
        if voce <= 0 or robo <= 0:
            break
    venceu = robo <= 0 and voce > 0
    if mostrar:
        print("Vitória! Você venceu o " + nome + "." if venceu else ("Empate: os dois caíram juntos." if voce <= 0 and robo <= 0 else ("Derrota: o " + nome + " venceu." if voce <= 0 else "Tempo esgotado: 20 turnos sem vencedor.")))
    return {"venceu": venceu, "vida": max(voce, 0), "turnos": turno}

